const gameId=new URL(location.href).searchParams.get('games_id');if(!/^\d+$/.test(gameId||''))throw new Error('This is not a game page.');const text=document.body.innerText,day=Number(text.match(/\bDay\s+(\d+)/i)?.[1])||null;
